    internal static int FtPutHex4(emon.Port.Cells @out, int v) {
        // Four upper-case hex digits of v, as bytes.
        int p = 4096;
        int d = 0;
        while (p > 0) {
            d = (v / p) % 16;
            if (d < 10) {
                emon.Port.CellsPush(@out, 48 + d);
            } else {
                emon.Port.CellsPush(@out, 55 + d);
            }
            p = p / 16;
        }
        return 0;
    }
