        emon.Port.CellsPush(@out, 10);
        return 0;
    }
    internal static int FtPutBegin(emon.Port.Cells @out) {
        // The bytes of `beginbfchar` and a newline.
        emon.Port.CellsPush(@out, 98);
        emon.Port.CellsPush(@out, 101);
        emon.Port.CellsPush(@out, 103);
        emon.Port.CellsPush(@out, 105);
        emon.Port.CellsPush(@out, 110);
        emon.Port.CellsPush(@out, 98);
        emon.Port.CellsPush(@out, 102);
        emon.Port.CellsPush(@out, 99);
        emon.Port.CellsPush(@out, 104);
        emon.Port.CellsPush(@out, 97);
        emon.Port.CellsPush(@out, 114);
        emon.Port.CellsPush(@out, 10);
        return 0;
    }
    [Xunit.Fact]
    public static void TestAThousandEntriesDefinedInReverseAreFound() {
        // A heap sort and a binary search: 3000 bfchars, each the code + 100,
        // written from the highest code down; every one must be found, and the
        // codes between and beyond must not be.
        emon.Port.Cells f = emon.Port.NewCells();
        emon.Port.Cells prog = emon.Port.NewCells();
        int i = 3000;
        int n = 0;
        int bad = 0;
        FtPutBegin(prog);
        while (i > 0) {
            FtPutEntry(prog, i + 4000, i + 100);
            i -= 1;
        }
        Pdffont.PfnFromCmap(f, emon.Testport.CellsBlob(prog), 1);
        i = 1;
        while (i <= 3000) {
            n = Pdffont.PfnMap(f, i + 4000);
            if (n != 1) {
                bad += 1;
            }
            if (Pdffont.PfnCp(f, 0) != (i + 100)) {
                bad += 1;
            }
            i += 1;
        }
        emon.Testport.AssertEq(bad, 0, "every entry found with its value");
        emon.Testport.AssertEq(Pdffont.PfnMap(f, 4000), 0, "below the first");
        emon.Testport.AssertEq(Pdffont.PfnMap(f, 7001), 0, "above the last");
        emon.Testport.AssertEq(Pdffont.PfnMap(f, 100), 0, "far below");
    }
    [Xunit.Fact]
    public static void TestACmapOverTheLimitIsCutAndSaysSo() {
        // 100,050 entries: the first 100,000 (in definition order) are kept, the
        // warning bit says the rest were dropped, and nothing faults.
        emon.Port.Cells f = emon.Port.NewCells();
        emon.Port.Cells prog = emon.Port.NewCells();
        int i = 0;
        FtPutBegin(prog);
        while (i < 100050) {
            FtPutEntry(prog, i % 65536, 65);
            i += 1;
        }
        Pdffont.PfnFromCmap(f, emon.Testport.CellsBlob(prog), 1);
        emon.Testport.AssertThat(((Pdffont.PfnWarn(f) / 4) % 2) > 0, "the limit warning is set");
        emon.Testport.AssertEq(Pdffont.PfnMap(f, 5), 1, "an entry inside the limit");
    }
    [Xunit.Fact]
    public static void TestACmapCutAtEveryByteNeverFaults() {
        // Every prefix of a CMap with every construct parses and answers.
        byte[] rows = emon.Testport.TestFile("fonts/cmaps.txt");
        emon.Port.Cells f = emon.Port.NewCells();
        emon.Port.Cells prog = emon.Port.NewCells();
        int n = emon.Port.BlobLen(rows);
        int pos = 0;
        int e = 0;
        int s0 = 0;
        int s1 = 0;
        int cut = 0;
        int total = 0;
        int tries = 0;
        while (pos < n) {
            e = FtNl(rows, pos);
            if ((pos < e) && (emon.Port.BlobU8(rows, pos) == 102)) {
                s0 = FtTab(rows, pos, e);
                s1 = FtTab(rows, s0 + 1, e);
                FtUnescape(rows, s0 + 1, s1, prog);
                total = emon.Port.CellsLen(prog);
                cut = 0;
                while (cut <= total) {
                    emon.Port.Cells piece = emon.Port.NewCells();
                    int j = 0;
                    while (j < cut) {
                        emon.Port.CellsPush(piece, emon.Port.CellsAt(prog, j));
                        j += 1;
                    }
                    Pdffont.PfnFromCmap(f, emon.Testport.CellsBlob(piece), 1);
                    Pdffont.PfnMap(f, 65);
                    Pdffont.PfnMap(f, 4660);
                    Pdffont.PfnFromCmap(f, emon.Testport.CellsBlob(piece), 2);
                    Pdffont.PfnCid(f, 65);
                    Pdffont.PfnCodeLen(f, 129, 64, -1, -1);
                    tries += 1;
                    cut += 1;
                }
            }
            pos = e + 1;
        }
        emon.Testport.AssertThat(tries > 100, "the prefixes were tried");
    }
}
